package com.InnovaServe.restaurant.entity;import com.InnovaServe.core.entity.TenantEntity;import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.UUID;
@Entity @Table(name="restaurant_order",schema="restaurant")public class RestaurantOrder extends TenantEntity{@Column(name="order_type",nullable=false,length=15)private String orderType;@Column(name="table_id")private UUID tableId;@Column(name="stay_id")private UUID stayId;@Column(nullable=false,length=10)private String status;@Column(name="order_source",nullable=false,length=10)private String orderSource;@Column(name="confirmation_status",nullable=false,length=15)private String confirmationStatus;@Column(name="confirmed_by")private UUID confirmedBy;@Column(name="confirmed_at")private LocalDateTime confirmedAt;@Column(name="bill_requested_at")private LocalDateTime billRequestedAt;@Column(name="opened_by")private UUID openedBy;@Column(name="created_at",insertable=false,updatable=false)private LocalDateTime createdAt;protected RestaurantOrder(){}public RestaurantOrder(UUID t,String type,UUID table,UUID stay,String source,boolean pending,UUID user){super(t);orderType=type;tableId=table;stayId=stay;status="open";orderSource=source;confirmationStatus=pending?"pending":"not_required";openedBy=user;}public UUID getTableId(){return tableId;}public UUID getStayId(){return stayId;}public String getStatus(){return status;}public String getConfirmationStatus(){return confirmationStatus;}public void confirm(UUID user){confirmationStatus="confirmed";confirmedBy=user;confirmedAt=LocalDateTime.now();}public void markBilled(){status="billed";}}
